scripts.script:
                                    import java.nio.file.*

                                    def srcDir = project.basedir
                                    def outputDir = new File(project.build.outputDirectory)
                                    def docrootTarget = new File(outputDir, "docroot")
                                    docrootTarget.mkdirs()

                                    // Helper function to copy files recursively with filters
                                    def copyDirWithFilters = { File source, File target, Closure filter ->
                                        if (!source.exists()) return
                                        source.eachFileRecurse { File file ->
                                            def relative = source.toPath().relativize(file.toPath()).toString()
                                            if (filter(file, relative)) {
                                                def destFile = new File(target, relative)
                                                if (file.isDirectory()) {
                                                    destFile.mkdirs()
                                                } else {
                                                    destFile.parentFile.mkdirs()
                                                    Files.copy(file.toPath(), destFile.toPath(), StandardCopyOption.REPLACE_EXISTING)
                                                }
                                            }
                                        }
                                    }

                                    // 1. Copy docroot resources:
                                    // **/*.gif, **/*.jpg, **/*.css, **/*.js (excluding resource/, build/, target/) -> docroot/
                                    log.info("Copying Demo docroot resources...")
                                    copyDirWithFilters(srcDir, docrootTarget, { File file, String rel ->
                                        def normalizedRel = rel.replace('\\', '/')
                                        if (normalizedRel.startsWith("resource/") || 
                                            normalizedRel.startsWith("build/") || 
                                            normalizedRel.startsWith("target/") || 
                                            normalizedRel.startsWith("pom.xml")) {
                                            return false
                                        }
                                        if (file.isDirectory()) return true
                                        return file.name.endsWith(".gif") || file.name.endsWith(".jpg") || file.name.endsWith(".css") || file.name.endsWith(".js")
                                    })

                                    // 2. Copy resource/webserver (excluding branding/) -> docroot/
                                    def webserverSrc = new File(srcDir, "resource/webserver")
                                    if (webserverSrc.exists()) {
                                        copyDirWithFilters(webserverSrc, docrootTarget, { File file, String rel ->
                                            def normalizedRel = rel.replace('\\', '/')
                                            return !normalizedRel.startsWith("branding")
                                        })
                                    }

                                    // 3. Copy resource/webserver/branding -> docroot/config/branding
                                    def brandingSrc = new File(srcDir, "resource/webserver/branding")
                                    def brandingDest = new File(docrootTarget, "config/branding")
                                    if (brandingSrc.exists()) {
                                        copyDirWithFilters(brandingSrc, brandingDest, { f, rel -> true })
                                    }

                                    // 4. Generate aribaweb.properties:
                                    log.info("Generating aribaweb.properties...")
                                    def propsFile = new File(outputDir, "aribaweb.properties")
                                    propsFile.parentFile.mkdirs()
                                    def writer = new PrintWriter(propsFile)
                                    writer.println("packaged-resource-extensions=awl,oss,csv,xml")
                                    writer.println("use-namespace-from-package=ariba.ui.meta")
                                    writer.println("depends-on=ariba.groovyloader,ariba.metaui")
                                    writer.close()

                                    // 5. Generate web.xml:
                                    log.info("Generating web.xml...")
                                    def webXmlFile = new File(project.build.directory, "web.xml")
                                    webXmlFile.parentFile.mkdirs()
                                    webXmlFile.text = """<?xml version="1.0" encoding="UTF-8"?>
<web-app xmlns="http://xmlns.jcp.org/xml/ns/javaee"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://xmlns.jcp.org/xml/ns/javaee http://xmlns.jcp.org/xml/ns/javaee/web-app_4_0.xsd"
         version="4.0">
  <display-name>Demo Application</display-name>
  <description>Demo Application</description>
  <servlet>
    <servlet-name>Demo</servlet-name>
    <servlet-class>ariba.ui.servletadaptor.AWDispatcherServlet</servlet-class>
  </servlet>
  <servlet-mapping>
    <servlet-name>Demo</servlet-name>
    <url-pattern>/AribaWeb/*</url-pattern>
  </servlet-mapping>
</web-app>
"""
